    if (tag && req.headers['if-none-match'] === tag) { res.writeHead(304); return res.end(); }
    const h = { 'content-type': type, 'cache-control': cache || 'no-cache', 'x-content-type-options': 'nosniff', ...(tag ? { etag: tag } : {}) };
