    if (!tz.readable) return send(403, 'text/plain', Buffer.from('teaser.mp4 is on the server but the server is not allowed to read it. Set its permissions to 644.'));
    const size = tz.size, m = /bytes=(\d*)-(\d*)/.exec(req.headers.range || ''); let a = 0, b = size - 1;
    if (m) { if (m[1] === '') { a = Math.max(0, size - +m[2]); } else { a = +m[1]; if (m[2] !== '') b = Math.min(b, +m[2]); } if (a > b || a >= size) { res.writeHead(416, { 'content-range': 'bytes */' + size }); return res.end(); } }
