  room.add(c); clients.add(c);
  const others = msg => { const f = frame(1, Buffer.from(JSON.stringify(msg))); for (const o of room) if (o !== c && !o.socket.destroyed) o.socket.write(f); };

  c.send({ type: 'welcome', id: c.id, room: code, host: [...room][0].id, players: [...room].filter(o => o !== c).map(o => o.p) });
  others({ type: 'join', player: c.p });

